SELECT Go.PIscr, Scuola.AnnoS, Go.Sede, [Prof.Cognome] & " " & [Prof.Nome] AS NominativoProf, [Go.Cognome] & " " & [Go.Nome] AS NominativoUc, Go.DataN, Comuni_1.Comune AS ComuneN, DateDiff("yyyy",[Go.DataN],Date())+(Format(Date(),"mmdd")<Format([Go.DataN],"mmdd")) AS Starost, Go.tel, Go.mail, Go.cel, Materia.Stejemo, Scuola.Razred, Scuola.Ore, Podruzica.Dove, Scuola.Posk AS preAFAM, Sola.Sola, Sola.Razred, Sola.Sek, Sola.Note, Scuola.DataI, Scuola.DataF, Scuola.DataI2, Scuola.DataF2, Go.Via, Comuni.Comune, Comuni.CAP
FROM Comuni AS Comuni_1 RIGHT JOIN (((((([Go] INNER JOIN Scuola ON Go.IdP = Scuola.IdP) LEFT JOIN Materia ON Scuola.IdM = Materia.IdM) LEFT JOIN Podruzica ON Scuola.IdD = Podruzica.IdD) LEFT JOIN Sola ON (Scuola.AnnoS = Sola.AnnoS) AND (Scuola.IdP = Sola.IdP)) LEFT JOIN Prof ON Scuola.IdPr = Prof.IdPr) LEFT JOIN Comuni ON Go.IdCR = Comuni.IdC) ON Comuni_1.IdC = Go.IdCN
GROUP BY Go.PIscr, Scuola.AnnoS, Go.Sede, [Prof.Cognome] & " " & [Prof.Nome], [Go.Cognome] & " " & [Go.Nome], Go.DataN, Comuni_1.Comune, DateDiff("yyyy",[Go.DataN],Date())+(Format(Date(),"mmdd")<Format([Go.DataN],"mmdd")), Go.tel, Go.mail, Go.cel, Materia.Stejemo, Scuola.Razred, Scuola.Ore, Podruzica.Dove, Scuola.Posk, Sola.Sola, Sola.Razred, Sola.Sek, Sola.Note, Scuola.DataI, Scuola.DataF, Scuola.DataI2, Scuola.DataF2, Go.Via, Comuni.Comune, Comuni.CAP
HAVING (((Scuola.AnnoS) Like [Inserire Anno Scolastico]))
ORDER BY Materia.Stejemo;
